(function (root) {
  'use strict';
  const defaults = {
    enabled: true,
    mode: 'all',
    compact: false,
    checkLabels: true,
    filterStories: true,
    filterVietsubChannels: true,
    keywords: [],
    blockedChannels: [],
    allowedChannels: []
  };
  const generated = [
    'ai generated', 'ai-generated', 'generated by ai', 'made with ai', 'created with ai',
    'ai music', 'ai cover', 'ai song', 'ai voice', 'ai animation', 'ai video',
    'ai art', 'ai film', 'ai movie', 'ai trailer', 'ai slop',
    'nhac ai', 'nhac tao boi ai', 'video ai', 'anh ai', 'giong doc ai',
    'tao bang ai', 'tao boi ai', 'do ai tao', 'tri tue nhan tao tao'
  ];
  const topics = [
    'ai', 'a.i.', 'artificial intelligence', 'generative ai', 'machine learning',
    'deep learning', 'tri tue nhan tao', 'hoc may', 'chatgpt', 'openai', 'gemini',
    'claude', 'midjourney', 'stable diffusion', 'suno', 'udio', 'deepseek',
    'copilot', 'runway', 'sora', 'kling', 'veo', 'llm'
  ];
  // A user-selected genre filter, not evidence that a video was made with AI.
  const storyTerms = ['xuyen ve', 'xuyen khong', 'xuyen den', 'trong sinh', 'tai sinh', 'chuyen sinh'];
  function normalize(value) {
    return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase().replace(/\s+/g, ' ').trim();
  }
  function includesTerm(text, term) {
    const haystack = normalize(text);
    const needle = normalize(term);
    if (!needle) return false;
    let index = haystack.indexOf(needle);
    while (index !== -1) {
      const before = haystack[index - 1] || '';
      const after = haystack[index + needle.length] || '';
      if (!/[\p{L}\p{N}_]/u.test(before) && !/[\p{L}\p{N}_]/u.test(after)) return true;
      index = haystack.indexOf(needle, index + 1);
    }
    return false;
  }
  function cleanSettings(value = {}) {
    const settings = { ...defaults, ...value };
    for (const key of ['keywords', 'blockedChannels', 'allowedChannels']) {
      settings[key] = Array.isArray(settings[key])
        ? [...new Set(settings[key].filter(v => typeof v === 'string').map(v => v.trim()).filter(Boolean))] : [];
    }
    settings.mode = settings.mode === 'generated' ? 'generated' : 'all';
    settings.enabled = settings.enabled !== false;
    settings.compact = settings.compact === true;
    settings.checkLabels = settings.checkLabels !== false;
    settings.filterStories = settings.filterStories !== false;
    settings.filterVietsubChannels = settings.filterVietsubChannels !== false;
    return settings;
  }
  function matchChannel(channel, entry) {
    return [channel.name, channel.handle, channel.path].some(value => value && normalize(value) === normalize(entry));
  }
  function classify(video, input) {
    const settings = cleanSettings(input);
    if (!settings.enabled) return null;
    if (video.aiLabel) return { type: 'label', reason: 'YouTube đánh dấu: Tạo bằng AI' };
    const channel = video.channel || {};
    if (settings.allowedChannels.some(entry => matchChannel(channel, entry))) return null;
    const blocked = settings.blockedChannels.find(entry => matchChannel(channel, entry));
    if (blocked) return { type: 'channel', reason: `Kênh bị chặn: ${blocked}` };
    if (settings.filterVietsubChannels && [channel.name, channel.handle].some(value => /viet[\s._-]*sub/.test(normalize(value)))) {
      return { type: 'channel', reason: 'Tên kênh hoặc handle chứa Vietsub' };
    }
    const text = [video.title, video.description, channel.name, channel.handle].filter(Boolean).join(' ');
    const custom = settings.keywords.find(term => includesTerm(text, term));
    if (custom) return { type: 'keyword', reason: `Từ khóa của bạn: ${custom}` };
    const story = settings.filterStories && storyTerms.find(term => includesTerm(video.title, term));
    if (story) return { type: 'story', reason: `Lọc tiêu đề truyện: ${story}` };
    const terms = settings.mode === 'all' ? [...generated, ...topics] : generated;
    const term = terms.find(term => includesTerm(text, term));
    return term ? { type: 'keyword', reason: `Có từ khóa: ${term}` } : null;
  }
  const api = { defaults, normalize, includesTerm, cleanSettings, classify };
  root.YouTubeAIFilter = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(globalThis);
